import type { Decorator, Preview } from '@storybook/web-components-vite';
import { setCustomElementsManifest } from '@storybook/web-components-vite';
import { withThemeByClassName } from '@storybook/addon-themes';
import '../src/tokens/prism-tokens.css';
import './preview.css';

// The manifest is generated by `npm run analyze` into dist/. Optional so that tests run before a build.
const manifests = import.meta.glob<{ default: unknown }>('../dist/custom-elements.json', { eager: true });
const cem = Object.values(manifests)[0]?.default;
if (cem) setCustomElementsManifest(cem);

/** Page background: the recommended gradient or worst-case solid backdrops (a11y-checklist.md §5.1). */
const withBackdrop: Decorator = (story, context) => {
  const backdrop = (context.globals['backdrop'] as string | undefined) ?? 'gradient';
  document.documentElement.setAttribute('data-sb-backdrop', backdrop);
  return story();
};

/** Text direction (RTL checks, ux-spec.md §1.7). */
const withDir: Decorator = (story, context) => {
  document.documentElement.dir = (context.globals['dir'] as string | undefined) ?? 'ltr';
  return story();
};

/** `[data-theme]` alias kept in sync with the `.dark` class set by addon-themes. */
const withThemeAlias: Decorator = (story, context) => {
  const theme = (context.globals['theme'] as string | undefined) ?? 'light';
  document.documentElement.setAttribute('data-theme', theme);
  return story();
};

const preview: Preview = {
  tags: ['autodocs'],
  parameters: {
    layout: 'padded',
    backgrounds: { disable: true },
    controls: { expanded: true },
    a11y: {
      test: 'error',
      options: {
        runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'] },
      },
    },
  },
  globalTypes: {
    backdrop: {
      description: 'Page backdrop',
      toolbar: {
        title: 'Backdrop',
        icon: 'photo',
        items: ['gradient', 'white', 'black', 'gray'],
        dynamicTitle: true,
      },
    },
    dir: {
      description: 'Text direction',
      toolbar: { title: 'Dir', icon: 'transfer', items: ['ltr', 'rtl'], dynamicTitle: true },
    },
  },
  initialGlobals: { backdrop: 'gradient', dir: 'ltr' },
  decorators: [
    withThemeAlias,
    withThemeByClassName({ themes: { light: '', dark: 'dark' }, defaultTheme: 'light', parentSelector: 'html' }),
    withBackdrop,
    withDir,
  ],
};

export default preview;
